@FiniteQM.ReconstructionGeometry.Representation.qubit_ball : ∀
  {catalogue : FiniteQM.ReconstructionGeometry.JordanStateCatalogue} {n : ℕ}
  {A : FiniteQM.ReconstructionGeometry.System n} (R : FiniteQM.ReconstructionGeometry.Representation catalogue A)
  {s : FiniteQM.ReconstructionArithmetic.SimpleEJA},
  R.tag.summands = [s] → s.IsQubitAlgebra → ∃ e, ⇑e '' A.states = FiniteQM.ClassicalExclusion.ball3

signatures.FiniteQM.ReconstructionGeometry.no_class:
@FiniteQM.ReconstructionGeometry.no_classical_composite_with_qubit : ∀
  {catalogue : FiniteQM.ReconstructionGeometry.JordanStateCatalogue} {a b c : ℕ}
  {A : FiniteQM.ReconstructionGeometry.System a} {B : FiniteQM.ReconstructionGeometry.System b}
  {AB : FiniteQM.ReconstructionGeometry.System c} (C : FiniteQM.ReconstructionGeometry.Composite A B AB)
  (RAB : FiniteQM.ReconstructionGeometry.Representation catalogue AB)
  (RB : FiniteQM.ReconstructionGeometry.Representation catalogue B) {s : FiniteQM.ReconstructionArithmetic.SimpleEJA},
  RB.tag.summands = [s] → s.IsQubitAlgebra → ¬RAB.tag.IsClassical

signatures.FiniteQM.ReconstructionGeometry.rank_two:
@FiniteQM.ReconstructionGeometry.rank_two_dim_four_ball : ∀
  {catalogue : FiniteQM.ReconstructionGeometry.JordanStateCatalogue} {n : ℕ}
  {A : FiniteQM.ReconstructionGeometry.System n} (R : FiniteQM.ReconstructionGeometry.Representation catalogue A),
  A.rank = 2 → A.dim = 4 → ∃ e, ⇑e '' A.states = FiniteQM.ClassicalExclusion.ball3

signatures.FiniteQM.ReconstructionGeometry.no_class:
@FiniteQM.ReconstructionGeometry.no_classical_factor_with_qubit : ∀
  {catalogue : FiniteQM.ReconstructionGeometry.JordanStateCatalogue} {a b c : ℕ}
  {A : FiniteQM.ReconstructionGeometry.System a} {B : FiniteQM.ReconstructionGeometry.System b}
  {AB : FiniteQM.ReconstructionGeometry.System c} (C : FiniteQM.ReconstructionGeometry.Composite A B AB)
  (RA : FiniteQM.ReconstructionGeometry.Representation catalogue A)
  (RB : FiniteQM.ReconstructionGeometry.Representation catalogue B)
  (RAB : FiniteQM.ReconstructionGeometry.Representation catalogue AB),
  RAB.tag.IsSimple ∨ RAB.tag.IsClassical →
    AB.dim = A.dim * B.dim → A.rank * B.rank ≤ AB.rank → 2 ≤ A.rank → B.rank = 2 → B.dim = 4 → ¬RA.tag.IsClassical

signatures.FiniteQM.CatalogueGeometry.extreme_of_un:
@FiniteQM.CatalogueGeometry.extreme_of_unique_affine_max : ∀ {n : ℕ} (S : Set (FiniteQM.ReconstructionGeometry.Space n))
  (f : FiniteQM.ReconstructionGeometry.Space n →ᵃ[ℝ] ℝ),
  ∀ z ∈ S, (∀ x ∈ S, f x ≤ f z) → (∀ x ∈ S, f x = f z → x = z) → z ∈ Set.extremePoints ℝ S

signatures.FiniteQM.ConcreteJordanProducts.classica:
@FiniteQM.ConcreteJordanProducts.classical_add_left : ∀ {r : ℕ} (a b c : Fin r → ℝ),
  FiniteQM.ConcreteJordanProducts.classicalMul (a + b) c =
    FiniteQM.ConcreteJordanProducts.classicalMul a c + FiniteQM.ConcreteJordanProducts.classicalMul b c

@FiniteQM.ConcreteJordanProducts.classical_normalized : ∀ {r : ℕ} (a : Fin r → ℝ),
  FiniteQM.ConcreteJordanProducts.classicalPositive a ∧ FiniteQM.ConcreteJordanProducts.classicalTrace a = 1 ↔
    a ∈ stdSimplex ℝ (Fin r)

signatures.FiniteQM.ClassicalModel.coord_one_unique:
@FiniteQM.ClassicalModel.coord_one_unique : ∀ {n : ℕ} {x : FiniteQM.ReconstructionGeometry.Space n},
  x ∈ FiniteQM.ClassicalModel.states n →
    ∀ (i : Fin (n + 1)), ((FiniteQM.ClassicalModel.basis n).coord i) x = 1 → x = (FiniteQM.ClassicalModel.basis n) i

signatures.FiniteQM.ClassicalModel.coords_probabili:
@FiniteQM.ClassicalModel.coords_probability : ∀ {n : ℕ} {x : FiniteQM.ReconstructionGeometry.Space n},
  x ∈ (FiniteQM.ClassicalModel.system n).states →
    (FiniteQM.ClassicalModel.basis n).coords x ∈ stdSimplex ℝ (Fin (n + 1))

@FiniteQM.SupportedJordanCatalogue.Entry.qubit_geometry : ∀ {J : FiniteQM.ReconstructionArithmetic.EJA}
  (self : FiniteQM.SupportedJordanCatalogue.Entry J) (s : FiniteQM.ReconstructionArithmetic.SimpleEJA),
